// 算出本周窗口：从 now 往前 days 天，ISO 字符串给 GitHub 搜索用
const cfg = $input.first().json;
const now = new Date();
const since = new Date(now.getTime() - Number(cfg.days) * 24 * 60 * 60 * 1000);
return [{
  json: {
    ...cfg,
    since: since.toISOString(),
    until: now.toISOString(),
    sinceDate: since.toISOString().slice(0, 10),
    untilDate: now.toISOString().slice(0, 10)
  }
}];

// 把三路结果捏成一份给模型的素材，长列表截断，避免 token 爆掉。
// safe()：某个分支这周没数据、或节点没执行时，不该让整条流挂掉。
// flatMap：搜索接口会返回多条 item，每条自带 items 数组，要摊平再数。
const safe = (nodeName) => {
  try { return $(nodeName).all().map(i => i.json); } catch (e) { return []; }
};

const cfgRaw = safe('Window');
const cfg = cfgRaw[0] || { repo: 'unknown', channel: '', language: 'EN', sinceDate: '', untilDate: '' };

const commits = safe('GET commits');
const prs = safe('GET merged PRs').flatMap(r => r.items || []);
const issues = safe('GET closed issues').flatMap(r => r.items || []);

const clean = (s) => String(s || '').replace(/\s+/g, ' ').trim();
const clip = (s, n) => (clean(s).length > n ? clean(s).slice(0, n) + '…' : clean(s));

const commitLines = commits.slice(0, 60).map(c =>
  '- ' + (c.commit && c.commit.author ? c.commit.author.name : 'unknown') + ': ' +
  clip(c.commit && c.commit.message ? c.commit.message.split('\n')[0] : '', 100)
);
const prLines = prs.slice(0, 40).map(p => '- #' + p.number + ' ' + clip(p.title, 120));
const issueLines = issues.slice(0, 40).map(i => '- #' + i.number + ' ' + clip(i.title, 120));

return [{
  json: {
    repo: cfg.repo,
    channel: cfg.channel,
    language: cfg.language,
    from: cfg.sinceDate,
    to: cfg.untilDate,
    commitCount: commits.length,
    prCount: prs.length,
    issueCount: issues.length,
    commits: commitLines.join('\n') || '- (none)',
    prs: prLines.join('\n') || '- (none)',
    issues: issueLines.join('\n') || '- (none)'
  }
}];

