// 拆出正文；如果模型拒答或返回异常，给一条可读的兜底
const cfg = $('Bundle').first().json;
const raw = $input.first().json;

let body = '';
try {
  const parts = raw.content || [];
  body = parts.filter(p => p.type === 'text').map(p => p.text).join('\n').trim();
} catch (e) {
  body = '';
}

if (!body) {
  body = `No narrative returned by the model (stop_reason: ${raw.stop_reason || 'unknown'}). Raw keys: ${Object.keys(raw).join(', ')}`;
}

const title = cfg.language === 'FR'
  ? `Resume hebdomadaire — ${cfg.repo} (${cfg.from} → ${cfg.to})`
  : `Weekly digest — ${cfg.repo} (${cfg.from} → ${cfg.to})`;

return [{ json: { channel: cfg.channel, title, body, repo: cfg.repo, from: cfg.from, to: cfg.to,
  commitCount: cfg.commitCount, prCount: cfg.prCount, issueCount: cfg.issueCount } }];

